-- 5. TẠO VIEW TRUY VẤN TỔNG HỢP
CREATE OR REPLACE VIEW "v_ChiTietSinhVien" AS
SELECT 
    s."MaSV", s."HoTenEncrypted", s."NgaySinh", s."GioiTinh",
    l."TenLop", k."TenKhoa", s."Email", s."DiemTB", s."XepLoai", s."TrangThai"
FROM "SinhVien" s
LEFT JOIN "LopHoc" l ON s."MaLop" = l."MaLop"
LEFT JOIN "Khoa" k ON l."MaKhoa" = k."MaKhoa";

-- TRUY VẤN KIỂM TRA DỮ LIỆU TỔNG CỘNG 250 SINH VIÊN
SELECT * FROM "v_ChiTietSinhVien" ORDER BY "MaSV" ASC;
